<script setup>
import { nextTick, reactive, ref } from 'vue';
import MButton from '../../../components/mds/MButton.vue';
import MInput from '../../../components/mds/MInput.vue';
import MSelect from '../../../components/mds/MSelect.vue';
import { toPeopleCreateDraft, toPeopleCreatePayload, validatePeopleEditDraft } from '../domain/people-write.mjs';

const props = defineProps({ organizations: { type: Array, default: () => [] }, saving: { type: Boolean, default: false }, serverError: { type: String, default: '' } });
const emit = defineEmits(['cancel', 'save']); const draft = reactive(toPeopleCreateDraft()); const errors = reactive({}); const nameInput = ref(null);
const levels = ['', 'Lãnh đạo', 'Quản lý', 'Chuyên viên', 'Phóng viên', 'Khác'].map((value) => ({ value, label: value || 'Chọn cấp bậc' }));
const categories = ['', 'VIP', 'Thường', 'Khác'].map((value) => ({ value, label: value || 'Chọn nhóm' }));
const statuses = ['Đang hoạt động', 'Tạm ngừng', 'Ngừng hợp tác'].map((value) => ({ value, label: value }));
function validate() { const next = { ...validatePeopleEditDraft(draft) }; if (!Number.isInteger(Number(draft.org_id)) || Number(draft.org_id) < 1) next.org_id = 'Cơ quan là bắt buộc.'; Object.keys(errors).forEach((key) => delete errors[key]); Object.assign(errors, next); return next; }
async function submit() { if (Object.keys(validate()).length) { await nextTick(); nameInput.value?.focus(); return; } emit('save', toPeopleCreatePayload(draft)); }
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto max-w-[880px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]" novalidate @submit.prevent="submit"><header class="flex items-start justify-between gap-4 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold leading-7">Thêm nhân sự</h1><p class="mt-1 text-[13px] leading-[18px] text-[var(--mds-text-secondary)]">Nhập thông tin công việc ban đầu. Dữ liệu cá nhân và phân công chăm sóc được quản lý ở luồng riêng.</p></div><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton></header><div class="grid gap-4 p-5 sm:grid-cols-2"><label class="block sm:col-span-2"><span class="mb-1.5 block text-[13px] font-medium">Họ và tên <span class="text-[var(--mds-danger)]">*</span></span><MInput ref="nameInput" v-model="draft.full_name" placeholder="Nhập họ và tên" :error="errors.full_name" :disabled="saving" /></label><label class="block sm:col-span-2"><span class="mb-1.5 block text-[13px] font-medium">Cơ quan <span class="text-[var(--mds-danger)]">*</span></span><MSelect v-model="draft.org_id" :options="organizations" placeholder="Chọn cơ quan" :error="errors.org_id" :disabled="saving || !organizations.length" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Cấp bậc</span><MSelect v-model="draft.level" :options="levels" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Chức vụ</span><MInput v-model="draft.position" placeholder="Ví dụ: Phóng viên" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Mảng phụ trách</span><MInput v-model="draft.beat" placeholder="Ví dụ: Công nghệ" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Nhóm</span><MSelect v-model="draft.category" :options="categories" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Điểm quan hệ</span><MInput v-model="draft.relationship_score" type="number" min="0" max="100" placeholder="0–100" :error="errors.relationship_score" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.status" :options="statuses" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Email công việc</span><MInput v-model="draft.email_work" type="email" placeholder="name@toasoan.vn" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Điện thoại công việc</span><MInput v-model="draft.phone_work" placeholder="Nhập số điện thoại" :disabled="saving" /></label></div><p v-if="serverError" role="alert" class="mx-5 mb-4 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ serverError }}</p><footer class="flex justify-end gap-2 border-t border-[var(--mds-border-light)] px-5 py-3"><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" :loading="saving" :disabled="saving" @click="submit">Tạo nhân sự</MButton></footer></form></section></template>
